    translations: {
      ur: "تاکہ تم ان کی پیٹھ پر چڑھ بیٹھو اور جب اس پر بیٹھ جاؤ پھر اپنے پروردگار کے احسان کو یاد کرو اور کہو کہ وہ (ذات) پاک ہے جس نے اس کو ہمارے زیر فرمان کر دیا اور ہم میں طاقت نہ تھی کہ اس کو بس میں کرلیتے",
      id: 'agar kamu duduk di atas punggungnya kemudian kamu ingat nikmat Tuhanmu apabila kamu telah duduk di atasnya; dan agar kamu mengucapkan, "Mahasuci (Allah) yang telah menundukkan semua ini bagi kami, padahal kami sebelumnya tidak mampu menguasainya',
      tr: 'Her sınıf varlığı yaratan O\'dur. Gemiler ve hayvanlardan binesiniz diye size binekler var etmiştir. Bütün bunlar; üzerlerine oturunca Rabbinizin nimetini anarak: "Bunları buyruğumuza veren ne yücedir; zaten bizim takatimiz bunlara yetmezdi; şüphesiz Rabbimize döneceğiz" demeniz içindir',
      tk: 'Her sınıf varlığı yaratan O\'dur. Gemiler ve hayvanlardan binesiniz diye size binekler var etmiştir. Bütün bunlar; üzerlerine oturunca Rabbinizin nimetini anarak: "Bunları buyruğumuza veren ne yücedir; zaten bizim takatimiz bunlara yetmezdi; şüphesiz Rabbimize döneceğiz" demeniz içindir',
      bn: "যাতে তোমরা তাদের পিঠের উপর আরোহণ কর। অতঃপর তোমাদের পালনকর্তার নেয়ামত স্মরণ কর এবং বল পবিত্র তিনি, যিনি এদেরকে আমাদের বশীভূত করে দিয়েছেন এবং আমরা এদেরকে বশীভূত করতে সক্ষম ছিলাম না।",
      ms: 'Supaya kamu duduk tetap di atasnya; kemudian kamu mengingati nikmat Tuhan kamu apabila kamu duduk tetap di atasnya, serta kamu (bersyukur dengan) mengucapkan:" Maha Suci Tuhan yang telah memudahkan kenderaan ini untuk kami, sedang kami sebelum itu tidak terdaya menguasainya',
      fa: "تا بر پشت آنها بخوبی قرار گیرید؛ سپس هنگامی که بر آنها سوار شدید، نعمت پروردگارتان را متذکّر شوید و بگویید: «پاک و منزّه است کسی که این را مسخّر ما ساخت، وگرنه ما توانایی تسخیر آن را نداشتیم؛",
      fr: "afin que vous vous installiez sur leurs dos, et qu'ensuite, après vous y être installés, vous vous rappeliez le bienfait de votre Seigneur et que vous disiez: «Gloire à Celui qui nous a soumis tout cela alors que nous n'étions pas capables de les dominer",
      ha: "Domin ku daidaitu a kan bãyansa, sa'an nan ku tuna ni'imar Ubangijinku a lõkacin da kuka daidaita a kansa kuma ku ce, \"Tsarki ya tabbata ga Wanda Ya hõre mana wannan alhãli kuwa ba mu kasance mãsu iya rinjãya gare Shi ba",
      sw: "Mpate kujituliza juu ya migongo ya hivyo mnavyovipanda, kisha mkumbuke neema ya Mola wenu kwenu hapo mnapopanda na mseme, «Sifa njema zote ni za Mwenyezi Mungu Aliyetudhalilishia (kipando) hiki, na hatukuwa ni wenye uwezo juu yake.»",
      ru: "чтобы вы поднимались на их спины (или палубы), а затем поминали милость вашего Господа после того, как поднялись на них, и говорили: «Пречист Тот, Кто подчинил нам это, ведь мы сами на такое были неспособны",
      az: "Ona görə ki, onları minəsiniz, sonra minib oturduğunuz zaman Rəbbinizin ne’mətini yada salaraq deyəsiniz: “Bunları bizə ram edən Allah pakdır, müqəddəsdir! (Əgər Allahın köməyi olmasaydı) bizim onlara gücümüz çatmazdı",
      ps: "د دې لپاره چې تاسو د هغو په شاګانو ښه برابر كېنئ، بیا د خپل رب نعمت رایاد كړئ، كله چې تاسو په دغه برابر كېنئ او ووایئ: پاكي ده هغه ذات لره چې زمونږ لپاره يې دا مسخر (او تابع) كړى دى۔ او مونږ ده لره په قابو كې راوستونكي نه یو",
      so: "Si aad ugu fariisataan si sugan dhabarradooda, markaas aad xusuusataan Nicmadda Rabbigiin marka aad dul fariisataan, oo tidhaahdaan: Xurmoo dhan waxaa iska leh Kan noo sakhiray waxakan, oo ma aheyn kuwo kara inaanu sameyno",
      uz: "Токи сизлар уларнинг устига ўрнашгайсизлар, сўнгра унга ўрнашиб олгач, Парвардигорингизнинг неъматини эслаб: «Бизларга бу (кема ёки от-улов)ни бўйсундириб қўйган зот (яъни, Аллоҳ барча айбу-нуқсондан) покдир. Бизлар ўзимиз бунга қодир эмас эдик",
      kk: 'Олардың үстіне мінсеңдер, сосын Раббыларыңның нығметін еске алып: "Бұны бізге бағындырған Алла пәк. Өйткені біз бұған жақындаса алмайтын едік" дейсіңдер',
      ku: "بۆ ئه‌وه‌ی له‌سه‌ر پشتیان جێگیر ببن، دوایش یادی نازو نیعمه‌تی په‌روه‌ردگارتان بکه‌نه‌وه کاتێك که سه‌قامگیر ده‌بن له‌سه‌ری، (چونکه جۆره‌ها هۆکاری هاتووچۆی بۆ سازاندوون) و بشڵێن: ستایش و به‌رزی و بێگه‌ردی بۆ ئه‌و زاته‌ی که ئه‌مه‌ی بۆ ڕه‌خساندوین (خۆ ئه‌گه‌ر ئه‌و به‌میهره‌بانی خۆی بۆی ڕام نه‌کردینایه‌) ئێمه نه‌مانده‌توانی ڕامیان بهێنین",
      bs: 'da se leđima njihovim služite i da se, kad na njima jahali budete, blagodati Gospodara svoga sjetite i da reknete: "Hvaljen neka je Onaj koji je dao da nam one služe, mi to sami ne bismo mogli postići',
      sq: "Të uleni mbi to dhe atëherë, pasi të jeni vendosur mbi to, ta përkujtoni të mirën që u dha Zoti juaj e të thoni: “Falënderuar qoftë Ai që i nënshtroi këto për neve, sepse ne nuk do të kishim mundësi ta bënim këtë",
      ky: "(Мунун себеби:) алардын үстүнө минип, кийин Раббиңердин нээматын эскерип: «Бизге ушуну моюн сундурган Аллаһ (кемчиликтүү сыпаттардан) Аруу-Таза! (Эгер Ал моюн сундурбаса) өзүбүздүн кудуретибиз жетмек эмес",
      tg: "Ва чун бар пушти онҳо қарор гирифтед, неъмати Парвардигоратонро ёд кунед ва бигӯед: «Пок аст он кас, ки инҳоро роми мо кард, вагарна моро тавони он набуд",
    },
