      id: 'Keduanya berkata, "Ya Tuhan kami, kami telah menzalimi diri kami sendiri. Jika Engkau tidak mengampuni kami dan memberi rahmat kepada kami, niscaya kami termasuk orang-orang yang rugi',
      tr: 'Her ikisi, "Rabbimiz! Kendimize yazık ettik; bizi bağışlamaz ve bize merhamet etmezsen biz kaybedenlerden oluruz" dediler',
      tk: 'Her ikisi, "Rabbimiz! Kendimize yazık ettik; bizi bağışlamaz ve bize merhamet etmezsen biz kaybedenlerden oluruz" dediler',
      bn: "তারা উভয়ে বললঃ হে আমাদের পালনকর্তা আমরা নিজেদের প্রতি জুলম করেছি। যদি আপনি আমাদেরকে ক্ষমা না করেন এবং আমাদের প্রতি অনুগ্রহ না করেন, তবে আমরা অবশ্যই অবশ্যই ধ্বংস হয়ে যাব।",
      ms: 'Mereka berdua merayu: "Wahai Tuhan kami, kami telah menganiaya diri kami sendiri, dan kalau Engkau tidak mengampunkan kami dan memberi rahmat kepada kami, nescaya menjadilah kami dari orang-orang yang rugi',
      fa: "گفتند: «پروردگارا! ما به خویشتن ستم کردیم! و اگر ما را نبخشی و بر ما رحم نکنی، از زیانکاران خواهیم بود!»",
      fr: "Tous deux dirent: «O notre Seigneur, nous avons fait du tort à nous-mêmes. Et si Tu ne nous pardonnes pas et ne nous fais pas miséricorde, nous serons très certainement du nombre des perdants»",
      ha: 'Suka ce: "Ya Ubangijinmu! Mun zãlunci kanmu. Kuma idan ba Ka gãfarta mana ba, kuma Ka yi mana rahama, haƙĩƙa, Munã kasancẽwa daga mãsu hasãra',
      sw: "Ādam na Ḥawwā’ walisema, «Ewe Mola wetu, tumejidhulumu nafsi zetu kwa kula kutoka kwenye mti ule. Na iwapo hutatusamehe na kuturehemu, tutakuwa ni miongoni mwa waliopoteza bahati zao katiku ulimengu wao na Akhera yao.» Maneno haya ndiyo yale aliyoyapokea Ādam kutoka kwa Mola wake akayatumia katika kumuomba, ndipo Mola wake Akaikubali toba yake",
      ru: "Они сказали: «Господь наш! Мы поступили несправедливо по отношению к себе, и если Ты не простишь нас и не смилостивишься над нами, то мы непременно окажемся одними из потерпевших урон»",
      az: "(Adəm və Həvva) “Ey Rəbbimiz! Biz özümüzə zülm etdik. Əgər bizi bağışlamasan, rəhm etməsən, biz, şübhəsiz ki, ziyana uğrayanlardan olarıq!” – dedilər",
      ps: "دوى وویل: اى زمونږه ربه! مونږ په خپلو ځانونو ظلم كړى دى او كه چېرې ته مونږ ونه بخښې او پر مونږ رحم ونه كړې (، نو) مونږ به خامخا لازمًا له تاوانیانو څخه شو",
      so: "Waxay yidhaahdeen: Rabbiyow! Waxaan u gefnay nafahayaga. Ee haddaa- dan noo dambi dhaafin, oo aadan noo Naxariisan, waxaan hubaal ka mid noqon kuwa ku sugan khasaaraha dhabta ah",
      uz: "Улар: «Парвардигоро, бизлар ўз жонимизга жабр-зулм қилдик. Агар бизларни мағфират ва раҳм қилмасанг, шубҳасиз, зиён кўргувчилардан бўлиб қолурмиз», дедилар",
      kk: "(Адам ата мен Хауа ана): «Раббымыз, біз өзімізге кесір істедік. Егер Сен бізді жарылқап, мәрхамет етпесең әлбетте зиян етушілерден боламыз» деді",
      ku: "(ئه‌وسا ئیتر هه‌ردووکیان هه‌ستیان به‌هه‌ڵه‌ی خۆیان کردو) وتیان: په‌روه‌ردگارا ئێمه سته‌ممان له خۆمان کرد، خۆ ئه‌گه‌ر لێمان خۆش نه‌بیت و به‌زه‌ییت پێماندا نه‌یه‌ته‌وه‌، ئه‌وه به‌ڕاستی ئێمه سوێند به خوا له خه‌ساره‌تمه‌ند و زه‌ره‌رمه‌ندانین",
      bs: 'Gospodaru naš" – rekoše oni – "sami smo sebi krivi, i ako nam Ti ne oprostiš i ne smiluješ nam se, sigurno ćemo biti izgubljeni',
      sq: "Ata të dy thanë: “Zoti ynë, ne i bëmë të padrejtë vetvetes, në qoftë se nuk na falë dhe nuk na mëshiron, ne me siguri do të jemi prej të shkatërruarve!”",
      ky: "Экөө (бушайман болушуп): “О, Раббибиз! Өзүбүзгө зулум кылып алдык! Эми, Сен бизди кечирбесең жана ырайым кылбасаң зыян тартуучулардан болуп калабыз” — дешти",
      tg: "Гуфтанд: «Эй Парвардигори мо, ба худ ситам кардем ва агар моро набахшӣ ва бар мо раҳмат накунӣ, аз зиёндидагон хоҳем буд»",
