    categoryId: "distress",
    title: "Upon encountering an enemy or those of authority #2",
    arabic: "اللَّهُمَّ أَنْتَ عَضُدِي، وَأَنْتَ نَصِيْرِي، بِكَ أَحُولُ، وَبِكَ أَصُولُ، وَبِكَ أُقَاتِلُ",
