    title: "Supplication of the traveller for the resident",
    arabic: "أَسْتَوْدِعُكُمُ اللَّهَ، الَّذِيْ لَا تَضِيْعُ وَدَائِعُهُ",
    translation: "I place you in the trust of Allah, whose trust is never misplaced.",
